from __future__ import annotations

import re
from pathlib import Path
import shutil

from .models import EndpointSpec, SpecField, SpecOutput

HEADER_LINES = [
    "# Generated by pykis codegen. DO NOT EDIT.",
    "# ruff: noqa",
    "# fmt: off",
    "",
]


def _with_header(lines: list[str]) -> list[str]:
    return HEADER_LINES + lines


def _normalize_filename(name: str) -> str:
    name = re.sub(r"^\[[^\]]+\]\s*", "", name)
    name = re.sub(r"\[v\d+_[^\]]+\]", "", name).strip()
    name = re.sub(r"\([^)]*\)", "", name).strip()
    name = re.sub(r"[^\w가-힣]+", "_", name)
    name = re.sub(r"_+", "_", name).strip("_")
    if not name:
        name = "unnamed"
    if name[0].isdigit():
        name = f"_{name}"
    return name.lower()


def _section_path(category: str | None, subcategory: str | None) -> Path:
    def _slug(value: str) -> str:
        value = re.sub(r"[^\w가-힣]+", "_", value).strip("_")
        if not value:
            value = "misc"
        if value[0].isdigit():
            value = f"_{value}"
        return value

    if category:
        return Path(_slug(category)) / _slug(subcategory or "misc")
    return Path(_slug(subcategory or "misc"))


def _class_name(name: str, suffix: str) -> str:
    base = re.sub(r"\[v\d+_[^\]]+\]", "", name).strip()
    base = re.sub(r"\([^)]*\)", "", base).strip()
    base = re.sub(r"[^0-9A-Za-z가-힣_]", "_", base)
    base = re.sub(r"_+", "_", base).strip("_")
    if not base:
        base = "Endpoint"
    if base[0].isdigit():
        base = f"_{base}"
    return f"{base}{suffix}"


def _field_name(code: str) -> str:
    name = re.sub(r"[^0-9A-Za-z_]", "_", code)
    name = re.sub(r"_+", "_", name).strip("_")
    if not name:
        name = "field"
    if name[0].isdigit():
        name = f"field_{name}"
    return name


def _field_type(field: SpecField, hint: dict[str, object] | None) -> tuple[str, set[str]]:
    if hint:
        enum_values = hint.get("enum")
        if isinstance(enum_values, list) and enum_values:
            literal_values = ", ".join(repr(value) for value in enum_values)
            return f"Literal[{literal_values}]", {"Literal"}
        kind = hint.get("kind")
        if kind == "int":
            return "int", set()
        if kind == "decimal":
            return "Decimal", {"Decimal"}
        if kind == "date":
            return "KisDate", {"KisDate"}
        if kind == "time":
            return "KisTime", {"KisTime"}
        if kind == "datetime":
            return "KisDateTime", {"KisDateTime"}
        if kind == "bool":
            return "KisBool", {"KisBool"}

    if field.code.lower().startswith(("output", "outblock")):
        return "object", set()
    type_name = (field.type_name or "").lower()
    if type_name == "number":
        return "Decimal", {"Decimal"}
    if type_name == "object":
        return "dict[str, object]", set()
    if type_name == "array":
        return "list[object]", set()
    return "str", set()


def _optional_type(py_type: str, imports: set[str]) -> str:
    if py_type == "KisDate":
        imports.add("KisDateOptional")
        return "KisDateOptional"
    if py_type == "KisTime":
        imports.add("KisTimeOptional")
        return "KisTimeOptional"
    if py_type == "KisDateTime":
        imports.add("KisDateTimeOptional")
        return "KisDateTimeOptional"
    return f"{py_type} | None"


def _render_fields(
    fields: list[SpecField],
    hints: dict[str, dict[str, object]] | None = None,
) -> tuple[list[str], set[str]]:
    if not fields:
        return [], set()

    lines: list[str] = []
    used_names: set[str] = set()
    imports: set[str] = set()
    for field in fields:
        name = _field_name(field.code)
        if name in used_names:
            name = f"{name}_field"
        used_names.add(name)
        hint = hints.get(field.code) if hints else None
        if not isinstance(hint, dict):
            hint = None
        py_type, needed = _field_type(field, hint)
        imports.update(needed)
        required = field.required
        if hint and "required" in hint:
            required = bool(hint["required"])

        desc = (field.description or "").strip() or (field.name or "").strip()
        if not required:
            optional_type = _optional_type(py_type, imports)
            lines.append(f"    {name}: {optional_type} = Field(default=None, alias={field.code!r})")
        else:
            lines.append(f"    {name}: {py_type} = Field(alias={field.code!r})")
        if desc:
            lines.append(f"    {desc!r}")
    return lines, imports


def _render_model(
    class_name: str, fields: list[SpecField], hints: dict[str, dict[str, object]] | None = None
) -> tuple[str, set[str]]:
    field_lines, imports = _render_fields(fields, hints)
    if not field_lines:
        field_lines = ["    pass"]
    lines = [f"class {class_name}(RawModel):", *field_lines]
    return "\n".join(lines), imports


def _render_typed_dict(
    class_name: str,
    fields: list[SpecField],
    hints: dict[str, dict[str, object]] | None = None,
) -> tuple[str, set[str]]:
    lines: list[str] = [f"class {class_name}(TypedDict):"]
    imports: set[str] = set()
    if not fields:
        lines.append("    pass")
        return "\n".join(lines), imports

    for field in fields:
        hint = hints.get(field.code) if hints else None
        if not isinstance(hint, dict):
            hint = None
        required = field.required
        if hint and "required" in hint:
            required = bool(hint["required"])
        py_type, needed = _field_type(field, hint)
        imports.update(needed)
        if required:
            lines.append(f"    {field.code}: {py_type}")
        else:
            optional_type = _optional_type(py_type, imports)
            lines.append(f"    {field.code}: NotRequired[{optional_type}]")
    return "\n".join(lines), imports


def _doc_line(text: str) -> str:
    return text.replace("\n", " ").replace('\"\"\"', "\\\"\\\"\\\"").strip()


def _render_call_docstring(
    spec: EndpointSpec,
    request_fields: list[SpecField],
    request_hint: dict[str, dict[str, object]] | None,
    request_model_name: str,
    request_dict_name: str,
    response_name: str,
) -> list[str]:
    lines: list[str] = []
    summary = _doc_line((spec.summary or spec.name or "").strip())
    description = _doc_line((spec.description or "").strip())
    if summary:
        lines.append(summary)
    if description:
        if summary:
            lines.append("")
        lines.append(description)
    if summary or description:
        lines.append("")

    lines.append("Args:")
    lines.append("    client (KisRawClient): API client.")
    lines.append(
        f"    request ({request_model_name} | {request_dict_name} | None): "
        "요청 파라미터. request 또는 kwargs 중 하나만 사용하세요."
    )
    lines.append(f"    **kwargs ({request_dict_name}): 요청 파라미터 키워드 입력.")
    lines.append("    headers (Mapping[str, str] | None): 추가 헤더.")
    if request_fields:
        lines.append("        Request fields:")
        for field in request_fields:
            hint = request_hint.get(field.code) if request_hint else None
            if not isinstance(hint, dict):
                hint = None
            required = field.required
            if hint and "required" in hint:
                required = bool(hint["required"])
            py_type, _ = _field_type(field, hint)
            if not required:
                py_type = _optional_type(py_type, set())
            desc = _doc_line((field.description or field.name or "").strip())
            optional = " optional" if not required else ""
            if desc:
                lines.append(f"            {field.code} ({py_type}): {desc}{optional}")
            else:
                lines.append(f"            {field.code} ({py_type}){optional}")
    lines.append("")
    lines.append("Returns:")
    lines.append(f"    {response_name}: 응답 모델")
    return lines


def generate_raw(specs: list[EndpointSpec], out_dir: Path, type_overrides: dict[str, object] | None = None) -> None:
    out_dir.mkdir(parents=True, exist_ok=True)
    keep_files = {"base.py", "types.py", "registry.py", "__init__.py"}
    for child in out_dir.iterdir():
        if child.is_dir():
            shutil.rmtree(child)
        elif child.is_file() and child.name not in keep_files:
            child.unlink()

    base_lines = [
        "from __future__ import annotations",
        "",
        "from datetime import date, datetime, time",
        "from decimal import Decimal",
        "from typing import Annotated, get_args, get_origin",
        "",
        "from pydantic import BaseModel, ConfigDict, Field, field_validator",
        "from pydantic.functional_validators import BeforeValidator",
        "",
        "",
        "def _parse_kis_date(value: object) -> date | None:",
        "    if value is None:",
        "        return None",
        "    if isinstance(value, date) and not isinstance(value, datetime):",
        "        return value",
        "    text = str(value).strip()",
        "    if not text:",
        "        return None",
        "    if text in {'0', '00000000'}:",
        "        return None",
        "    if text.isdigit() and len(text) == 8:",
        "        return datetime.strptime(text, '%Y%m%d').date()",
        "    return datetime.fromisoformat(text).date()",
        "",
        "",
        "def _parse_kis_time(value: object) -> time | None:",
        "    if value is None:",
        "        return None",
        "    if isinstance(value, time):",
        "        return value",
        "    text = str(value).strip()",
        "    if not text:",
        "        return None",
        "    if text in {'0', '000000', '0000'}:",
        "        return None",
        "    if text.isdigit() and len(text) in (6, 4):",
        "        fmt = '%H%M%S' if len(text) == 6 else '%H%M'",
        "        return datetime.strptime(text, fmt).time()",
        "    return datetime.fromisoformat(text).time()",
        "",
        "",
        "def _parse_kis_datetime(value: object) -> datetime | None:",
        "    if value is None:",
        "        return None",
        "    if isinstance(value, datetime):",
        "        return value",
        "    text = str(value).strip()",
        "    if not text:",
        "        return None",
        "    if text in {'0', '00000000000000'}:",
        "        return None",
        "    if text.isdigit() and len(text) == 14:",
        "        return datetime.strptime(text, '%Y%m%d%H%M%S')",
        "    return datetime.fromisoformat(text)",
        "",
        "",
        "def _parse_kis_bool(value: object) -> bool | None:",
        "    if value is None:",
        "        return None",
        "    if isinstance(value, bool):",
        "        return value",
        "    text = str(value).strip().upper()",
        "    if not text:",
        "        return None",
        "    if text in {'Y', 'YES', 'TRUE', '1'}:",
        "        return True",
        "    if text in {'N', 'NO', 'FALSE', '0'}:",
        "        return False",
        "    return bool(text)",
        "",
        "",
        "KisDate = Annotated[date, BeforeValidator(_parse_kis_date)]",
        "KisTime = Annotated[time, BeforeValidator(_parse_kis_time)]",
        "KisDateTime = Annotated[datetime, BeforeValidator(_parse_kis_datetime)]",
        "KisBool = Annotated[bool, BeforeValidator(_parse_kis_bool)]",
        "KisDateOptional = Annotated[date | None, BeforeValidator(_parse_kis_date)]",
        "KisTimeOptional = Annotated[time | None, BeforeValidator(_parse_kis_time)]",
        "KisDateTimeOptional = Annotated[datetime | None, BeforeValidator(_parse_kis_datetime)]",
        "",
        "",
        "def _unwrap_annotated(tp: object) -> object:",
        "    if get_origin(tp) is Annotated:",
        "        return get_args(tp)[0]",
        "    return tp",
        "",
        "",
        "def _is_optional(tp: object) -> bool:",
        "    tp = _unwrap_annotated(tp)",
        "    return type(None) in get_args(tp)",
        "",
        "",
        "class RawModel(BaseModel):",
        "    model_config = ConfigDict(extra='ignore', populate_by_name=True, union_mode='left_to_right', use_attribute_docstrings=True)",
        "",
        "    @field_validator('*', mode='before')",
        "    @classmethod",
        "    def _blank_optional_to_none(cls, value: object, info):",
        "        if isinstance(value, str) and not value.strip():",
        "            field = cls.model_fields.get(info.field_name)",
        "            if field and _is_optional(field.annotation):",
        "                return None",
        "        field = cls.model_fields.get(info.field_name)",
        "        if field:",
        "            annotation = _unwrap_annotated(field.annotation)",
        "            if get_origin(annotation) is list and isinstance(value, dict):",
        "                return [value]",
        "        return value",
        "",
    ]
    (out_dir / "base.py").write_text("\n".join(_with_header(base_lines)), encoding="utf-8")

    registry_lines = [
        "from __future__ import annotations",
        "",
        "from .types import Endpoint",
        "",
        "ENDPOINTS: dict[str, Endpoint] = {}",
        "",
    ]

    init_lines = [
        "from __future__ import annotations",
        "",
        "from .types import Endpoint",
        "",
        "ENDPOINTS: dict[str, Endpoint]",
        "_REGISTRY_IMPORT_ERROR: Exception | None",
        "",
        "try:",
        "    from .registry import ENDPOINTS",
        "    _REGISTRY_IMPORT_ERROR = None",
        "except Exception as exc:",
        "    ENDPOINTS = {}",
        "    _REGISTRY_IMPORT_ERROR = exc",
        "    print(f\"[pykis.api.raw] registry import failed: {exc}\")",
        "",
        "def ensure_registry() -> dict[str, Endpoint]:",
        "    if _REGISTRY_IMPORT_ERROR is not None:",
        "        raise RuntimeError(\"pykis.api.raw registry unavailable; generate endpoints first\") from _REGISTRY_IMPORT_ERROR",
        "    return ENDPOINTS",
        "",
        "__all__ = ['Endpoint', 'ENDPOINTS', 'ensure_registry']",
    ]

    for spec in specs:
        folder = out_dir / _section_path(spec.category, spec.subcategory)
        folder.mkdir(parents=True, exist_ok=True)
        _ensure_package_dirs(folder, out_dir)

        filename = f"{_normalize_filename(spec.name)}__{spec.id.replace('-', '_')}.py"
        module_path = folder / filename

        req_name = _class_name(spec.name, "Request")
        res_name = _class_name(spec.name, "Response")

        endpoint_hint: dict[str, object] = {}
        if type_overrides:
            raw_hint = type_overrides.get(spec.id)
            if isinstance(raw_hint, dict):
                endpoint_hint = raw_hint

        def _as_hint_map(value: object) -> dict[str, dict[str, object]]:
            if not isinstance(value, dict):
                return {}
            normalized: dict[str, dict[str, object]] = {}
            for key, item in value.items():
                if isinstance(item, dict):
                    normalized[str(key)] = item
            return normalized

        request_hint = _as_hint_map(endpoint_hint.get("request"))
        response_hint = _as_hint_map(endpoint_hint.get("response"))
        output_hint = _as_hint_map(endpoint_hint.get("outputs"))
        output_kinds_raw = endpoint_hint.get("output_kinds")
        output_kinds = output_kinds_raw if isinstance(output_kinds_raw, dict) else {}
        output_aliases_raw = endpoint_hint.get("output_aliases")
        output_aliases = output_aliases_raw if isinstance(output_aliases_raw, dict) else {}
        extra_fields_raw = endpoint_hint.get("extra_fields")
        extra_fields = extra_fields_raw if isinstance(extra_fields_raw, dict) else {}

        request_fields = spec.request.query + spec.request.body
        response_fields = list(spec.response.body)
        extra_response = extra_fields.get("response") if isinstance(extra_fields.get("response"), list) else []
        for extra in extra_response:
            response_fields.append(SpecField.model_validate(extra))

        module_lines = [
            "from __future__ import annotations",
            "",
            "from typing import Literal, Mapping, NotRequired, Protocol, TYPE_CHECKING, TypedDict, Unpack, overload",
            "from decimal import Decimal",
            "",
            "from pydantic import Field",
            "",
            "from pykis.api.raw.base import RawModel, KisBool, KisDate, KisTime, KisDateTime, KisDateOptional, KisTimeOptional, KisDateTimeOptional",
            "from pykis.api.raw.types import Endpoint",
            "",
            "if TYPE_CHECKING:",
            "    from pykis.api.client import KisRawClient",
            "    from requests import Response as RequestsResponse",
            "",
        ]

        request_model_src, req_imports = _render_model(req_name, request_fields, request_hint)
        module_lines.append(request_model_src)
        module_lines.append("")

        request_dict_name = f"{req_name}Dict"
        request_dict_src, _ = _render_typed_dict(request_dict_name, request_fields, request_hint)
        module_lines.append(request_dict_src)
        module_lines.append("")

        output_models: list[str] = []
        output_class_names: list[str] = []
        output_fields: list[str] = []
        for output in spec.response.outputs:
            output_code = output.code
            class_suffix = re.sub(r"[^0-9A-Za-z]+", "_", output_code).title().replace("_", "")
            output_class = _class_name(spec.name, class_suffix)
            output_class_names.append(output_class)
            field_hints = output_hint.get(output_code, {})
            output_fields_list = list(output.fields)
            extra_outputs = extra_fields.get("outputs") if isinstance(extra_fields.get("outputs"), dict) else {}
            for extra in (extra_outputs.get(output_code) or []):
                output_fields_list.append(SpecField.model_validate(extra))
            output_model_src, _ = _render_model(output_class, output_fields_list, field_hints)
            output_models.append(output_model_src)

            kind_hint = output_kinds.get(output_code) if isinstance(output_kinds, dict) else None
            kind = kind_hint if isinstance(kind_hint, str) else output.kind
            if kind == "array":
                field_type = f"list[{output_class}]"
            else:
                field_type = output_class
            alias = output_aliases.get(output_code) if isinstance(output_aliases, dict) else None
            if isinstance(alias, str) and alias != output_code:
                output_fields.append(f"    {output_code}: {field_type} = Field(alias={alias!r})")
            else:
                output_fields.append(f"    {output_code}: {field_type} = Field(alias={output_code!r})")
            output_desc = (output.name or "").strip()
            if output_desc:
                output_fields.append(f"    {output_desc!r}")

        if output_models:
            module_lines.extend(output_models)
            module_lines.append("")
            envelope_lines, _ = _render_fields(response_fields, response_hint)
            response_lines = [f"class {res_name}(RawModel):", *envelope_lines, *output_fields]
            module_lines.append("\n".join(response_lines))
        else:
            response_model_src, _ = _render_model(res_name, response_fields, response_hint)
            module_lines.append(response_model_src)
        module_lines.append("")

        all_names = ["ENDPOINT", req_name, request_dict_name, res_name, *output_class_names, "call"]
        module_lines.extend([
            f"_ENDPOINT: Endpoint[{req_name}, {res_name}] = Endpoint(",
            f"    id={spec.id!r},",
            f"    name={spec.name!r},",
            f"    method={spec.method!r},",
            f"    path={spec.path!r},",
            f"    request_model={req_name},",
            f"    response_model={res_name},",
            f"    summary={spec.summary!r},",
            f"    description={spec.description!r},",
            f"    real_tr_id={spec.real_tr_id!r},",
            f"    demo_tr_id={spec.virtual_tr_id!r},",
            f"    auth_required={_has_header(spec.request.headers, 'authorization')},",
            f"    hashkey_required={_has_header(spec.request.headers, 'hashkey')},",
            ")",
            "",
            "if TYPE_CHECKING:",
            "    class _EndpointWithCall(Protocol):",
            "        @overload",
            f"        def call(self, client: KisRawClient, request: {req_name}, *, headers: Mapping[str, str] | None = None) -> tuple[{res_name}, RequestsResponse]: ...",
            "        @overload",
            f"        def call(self, client: KisRawClient, request: {request_dict_name}, *, headers: Mapping[str, str] | None = None) -> tuple[{res_name}, RequestsResponse]: ...",
            "        @overload",
            f"        def call(self, client: KisRawClient, *, headers: Mapping[str, str] | None = None, **kwargs: Unpack[{request_dict_name}]) -> tuple[{res_name}, RequestsResponse]: ...",
            "    ENDPOINT: _EndpointWithCall = _ENDPOINT",
            "else:",
            "    ENDPOINT = _ENDPOINT",
            "",
            "@overload",
            f"def call(client: KisRawClient, request: {req_name}, *, headers: Mapping[str, str] | None = None) -> {res_name}: ...",
            "@overload",
            f"def call(client: KisRawClient, request: {request_dict_name}, *, headers: Mapping[str, str] | None = None) -> {res_name}: ...",
            "@overload",
            f"def call(client: KisRawClient, *, headers: Mapping[str, str] | None = None, **kwargs: Unpack[{request_dict_name}]) -> {res_name}: ...",
            *[
                "def call(",
                f"    client: KisRawClient,",
                f"    request: {req_name} | {request_dict_name} | None = None,",
                f"    *,",
                f"    headers: Mapping[str, str] | None = None,",
                f"    **kwargs: Unpack[{request_dict_name}],",
                f") -> {res_name}:",
                "    \"\"\"",
                *[
                    f"    {line}"
                    for line in _render_call_docstring(
                        spec,
                        request_fields,
                        request_hint,
                        req_name,
                        request_dict_name,
                        res_name,
                    )
                ],
                "    \"\"\"",
                "    if request is None:",
                "        request = kwargs",
                "    elif kwargs:",
                "        raise ValueError(\"Provide either request or kwargs, not both.\")",
                f"    return client.call(ENDPOINT, request, headers=headers)[0]",
            ],
            "",
            f"__all__ = {all_names!r}",
        ])

        module_path.write_text("\n".join(_with_header(module_lines)), encoding="utf-8")

        module_import = _module_import(out_dir, module_path)
        registry_lines.append(f"from {module_import} import ENDPOINT as ENDPOINT_{spec.id.replace('-', '_')}")
        registry_lines.append(f"ENDPOINTS[{spec.id!r}] = ENDPOINT_{spec.id.replace('-', '_')}")
        registry_lines.append("")

    (out_dir / "registry.py").write_text("\n".join(_with_header(registry_lines)), encoding="utf-8")
    (out_dir / "__init__.py").write_text("\n".join(_with_header(init_lines)), encoding="utf-8")


def _module_import(root: Path, module_path: Path) -> str:
    rel = module_path.relative_to(root).with_suffix("")
    parts = ["pykis", "api", "raw", *rel.parts]
    return ".".join(parts)


def _has_header(headers: list[SpecField], code: str) -> bool:
    target = code.lower()
    return any(field.code.lower() == target for field in headers)


def _ensure_package_dirs(folder: Path, root: Path) -> None:
    current = folder
    while True:
        init_path = current / "__init__.py"
        if not init_path.exists():
            init_path.write_text("", encoding="utf-8")
        if current == root:
            break
        if current.parent == current:
            break
        current = current.parent
